sp_widget.client_script:
function ($scope, $rootScope, spModal, spUtil) {
  var c = this;

  // Load selected note from Notes List
  $rootScope.$on('selectNote', function (event, id) {
    var noteID = $rootScope.noteID || id;
    if (!noteID) return;

    c.server.get({ action: 'getNote', noteID: noteID }).then(function (r) {
      if (r && r.data && r.data.note) {
        c.data.noteID = r.data.note.sys_id || '';
        c.data.title  = r.data.note.title  || '';
        c.data.note   = r.data.note.note   || '';
      }
    });
  });

  // Update title/body with debounce
  c.updateNote = function (which) {
    if (!c.data.noteID) return;
    var payload = {
      action: 'updateNote',
      noteID: c.data.noteID
    };
    if (which === 'title') payload.noteTitle = c.data.title;
    if (which === 'body')  payload.noteBody  = c.data.note;

    c.server.get(payload).then(function () {
      // let the list know (optional)
      $rootScope.$emit('noteUpdated', {
        noteID: c.data.noteID,
        title:  c.data.title,
        body:   c.data.note
      });
    });
  };

  // Confirm, then delete on the server (standalone; no c.deleteNote needed)
  c.confirmDelete = function () {
    if (!c.data.noteID) return;

    spModal.confirm("Are you sure you want to delete this Note record?")
      .then(function (confirmed) {
        if (!confirmed) return;

        var deletedTitle = c.data.title;

        c.server.get({
          action: 'deleteNote',
          noteID: c.data.noteID
        }).then(function (r) {
          if (r && r.data && r.data.deleted) {
            // Clear local form
            c.data.noteID = '';
            c.data.title  = '';
            c.data.note   = '';

            // Tell the list a note was removed (optional, if your list listens)
            $rootScope.$emit('noteDeleted', { noteID: r.data.deleted });

            // User feedback
            spUtil.addTrivialMessage("The '" + deletedTitle + "' record has been deleted.");
          }
        });
      });
  };
}

sp_widget.script:
(function () {

  // Helper: only allow the owner to read/update/delete (optional but recommended)
  function isOwner(rec) {
    return String(rec.getValue('user') || '') === String(gs.getUserID() || '');
  }

  if (!input || !input.noteID)
    return;

  var note = new GlideRecord('x_snc_createnotes_note');
  if (!note.get(input.noteID))
    return;

  // Optional security guard
  if (!isOwner(note)) {
    data.error = 'Not authorized to access this note.';
    return;
  }

  if (input.action === 'getNote') {
    data.note = {};
    $sp.getRecordValues(data.note, note, 'title,note,sys_id');
    return;
  }

  if (input.action === 'updateNote') {
    // Only set fields that were actually provided by the client
    if (Object.prototype.hasOwnProperty.call(input, 'noteTitle'))
      note.setValue('title', input.noteTitle || '');

    if (Object.prototype.hasOwnProperty.call(input, 'noteBody'))
      note.setValue('note', input.noteBody || '');

    note.update();

    // Return updated preview (null-safe)
    data.title = String(note.getValue('title') || '');
    var body = String(note.getValue('note') || '');
    data.note = body.substring(0, 20);
    return;
  }

  if (input.action === 'deleteNote') {
    var deletedId = String(note.getUniqueValue() || '');
    note.deleteRecord();
    data.deleted = deletedId; // lets the client tell the List to remove it
    return;
  }

})();
